function GlassBatchFurnaceMaker.completeMaking(m) local q=1.0+(GlassBatchFurnaceMaker.getQualityBonus()/100); if GlassBatchFurnaceMaker.maker then q=q+(GlassBatchFurnaceMaker.maker.skill/140) end; q=math.min(2.5,q); GlassBatchFurnaceMaker.productStock[m.productType]=(GlassBatchFurnaceMaker.productStock[m.productType] or 0)+m.quantity; GlassBatchFurnaceMaker.totalProducts=GlassBatchFurnaceMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GlassBatchFurnaceMaker.maker then GlassBatchFurnaceMaker.maker.itemsMade=GlassBatchFurnaceMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GlassBatchFurnaceMaker.maker.skill=math.min(100,GlassBatchFurnaceMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pec izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"glassbatchfurnace.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
